import{_ as e,o as a,c as t,ae as s}from"./chunks/framework.EHGTsUvI.js";const c=JSON.parse('{"title":"Liquid Silos","description":"","frontmatter":{"title":"Liquid Silos"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/liquidsilos.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/liquidsilos.md"}'),o={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/liquidsilos.md"};function l(n,i,r,d,u,p){return a(),t("div",null,[...i[0]||(i[0]=[s(`<h1 id="liquid-silos" tabindex="-1">Liquid Silos <a class="header-anchor" href="#liquid-silos" aria-label="Permalink to &quot;Liquid Silos&quot;">​</a></h1><p>Liquid Silos are storage buildings used to store <strong>liquid products</strong>. They allow players to store large quantities of liquids without needing to keep them inside trailers or other vehicles.</p><p>Liquid Silos are particularly useful for large-scale production chains where liquids need to be stored before being transported to factories or other locations.</p><h2 id="building-information" tabindex="-1">Building Information <a class="header-anchor" href="#building-information" aria-label="Permalink to &quot;Building Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Building</td><td>Liquid Silo</td></tr><tr><td>Purpose</td><td>Liquid Storage</td></tr><tr><td>Capacity</td><td>50 - 100 - 300 Units</td></tr><tr><td>Storage Type</td><td>Liquids</td></tr><tr><td>Build Menu</td><td>Create &gt; Buildings</td></tr></tbody></table><h2 id="stored-liquids" tabindex="-1">Stored Liquids <a class="header-anchor" href="#stored-liquids" aria-label="Permalink to &quot;Stored Liquids&quot;">​</a></h2><p>Liquid Silos can be used to store compatible liquid products such as:</p><ul><li>Milk</li><li>Free-Range Milk</li><li>Chocolate Milk</li><li>Grape Juice</li></ul><p>The silo is designed for storing liquid products rather than boxed crops or finished factory products.</p><h2 id="how-to-use-a-liquid-silo" tabindex="-1">How to Use a Liquid Silo <a class="header-anchor" href="#how-to-use-a-liquid-silo" aria-label="Permalink to &quot;How to Use a Liquid Silo&quot;">​</a></h2><h3 id="_1-purchase-the-silo" tabindex="-1">1. Purchase the Silo <a class="header-anchor" href="#_1-purchase-the-silo" aria-label="Permalink to &quot;1. Purchase the Silo&quot;">​</a></h3><p>Open the <strong>Create</strong> menu and purchase a Liquid Silo.</p><p>Place the silo somewhere accessible to your farming equipment and transport vehicles.</p><h3 id="_2-load-liquids" tabindex="-1">2. Load Liquids <a class="header-anchor" href="#_2-load-liquids" aria-label="Permalink to &quot;2. Load Liquids&quot;">​</a></h3><p>Bring the required liquid to the Liquid Silo using a suitable vehicle or trailer.</p><p>Unload the liquid into the silo&#39;s storage area.</p><p>The liquid will be added to the silo&#39;s available storage.</p><h3 id="_3-store-liquids" tabindex="-1">3. Store Liquids <a class="header-anchor" href="#_3-store-liquids" aria-label="Permalink to &quot;3. Store Liquids&quot;">​</a></h3><p>Once the liquid has been deposited, it remains stored inside the silo.</p><p>The silo can hold up to the selected storage capacity.</p><h3 id="_4-remove-liquids" tabindex="-1">4. Remove Liquids <a class="header-anchor" href="#_4-remove-liquids" aria-label="Permalink to &quot;4. Remove Liquids&quot;">​</a></h3><p>When you need the stored liquid for selling or production, use a suitable vehicle or trailer at the silo&#39;s loading area.</p><p>The stored liquid can then be transferred into the vehicle for transportation.</p><h2 id="liquid-storage-chain" tabindex="-1">Liquid Storage Chain <a class="header-anchor" href="#liquid-storage-chain" aria-label="Permalink to &quot;Liquid Storage Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Animal / Production</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    Liquid</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  Liquid Silo</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Factory       Sell</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Production   Sell Point</span></span></code></pre></div><h2 id="uses" tabindex="-1">Uses <a class="header-anchor" href="#uses" aria-label="Permalink to &quot;Uses&quot;">​</a></h2><p>Liquid Silos are especially useful for:</p><ul><li>Storing liquids between production runs</li><li>Building up large quantities of ingredients</li><li>Supplying production factories</li><li>Reducing the need for multiple trailers</li><li>Preparing liquids for large production batches</li></ul><blockquote><p><strong>Tip:</strong> Liquid Silos are particularly useful when running factories that require large quantities of liquid ingredients, such as the <strong>Chocolate Milk Factory</strong>, where milk is used as one of the main production ingredients.</p></blockquote>`,29)])])}const q=e(o,[["render",l]]);export{c as __pageData,q as default};
